import{_ as a,o as i,c as s,a6 as n}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Desarrollo de plugins","description":"","frontmatter":{"title":"Desarrollo de plugins","docId":"developer.plugins.index","translationKey":"developer.plugins.index","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"690689449dfe463405cff0ea6b3a33979249bbe68c598ee7e8ca862eedd704dc","translationRevision":"a9caff870e37cdd6580230f76472afb22e84e7a310c6e0775f31a673b6bb3f21","order":240},"headers":[],"relativePath":"es/developer/plugins/index.md","filePath":"es/developer/plugins/index.md","lastUpdated":1794611623000}'),t={name:"es/developer/plugins/index.md"};function o(r,e,l,d,c,p){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="plugin-development-overview" tabindex="-1">Desarrollo de plugins <a class="header-anchor" href="#plugin-development-overview" aria-label="Permalink to &quot;Desarrollo de plugins {#plugin-development-overview}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Elige el límite más pequeño que proporcione tu integración. TikTools descubre paquetes en raíces integradas, de usuario y de desarrollo; añadir un paquete no exige compilar un plugin concreto dentro del host. Usa devkit/SDK compatibles y un perfil privado antes de probar efectos.</p><h2 id="follow-the-authoring-path" tabindex="-1">Seguir el recorrido de autoría <a class="header-anchor" href="#follow-the-authoring-path" aria-label="Permalink to &quot;Seguir el recorrido de autoría {#follow-the-authoring-path}&quot;">​</a></h2><ol><li>Empieza con <a href="./quickstart.html">inicio rápido</a> para crear, validar y compilar un paquete aislado.</li><li>Elige <a href="./runtimes.html">runtime</a> según dependencias nativas y confianza, no solo por extensión.</li><li>Declara <a href="./permissions-ui.html">permisos e interfaz</a> para que el host revise efectos y renderice configuración.</li><li>Usa <a href="./packaging-registry.html">empaquetado y registro</a> para integridad, confianza del editor y actualizaciones.</li></ol><p>La autoridad Rust es <code>crates/tiktools-plugin-api</code>: validación de manifiestos, protocolo y contratos de interfaz. <code>crates/tiktools-plugin-sdk</code> proporciona la API Rust; <code>packages/plugin-sdk</code> contiene utilidades TypeScript y el <a href="https://github.com/nglmercer/TikTools-app/blob/remake/packages/plugin-sdk/plugin.schema.json" target="_blank" rel="noreferrer">esquema del editor</a>. La carga corresponde a <code>crates/tiktools-plugin-loader</code>, no al frontend.</p><h2 id="understand-contributions" tabindex="-1">Entender las contribuciones <a class="header-anchor" href="#understand-contributions" aria-label="Permalink to &quot;Entender las contribuciones {#understand-contributions}&quot;">​</a></h2><p>Una acción solicita efectos mediante resultados tipados. Las fuentes publican disparadores; los observadores reciben sobres estables <code>{topic,data}</code> con entrega acotada. Los procesadores añaden evidencia sin efectos en <code>event.intel</code>, con plazos, combinación determinista y aislamiento de salud. Ajustes/acciones declarativos permiten configuración habitual renderizada por el host. Una página compilada usa un intermediario restringido en su propio marco/ventana; su script nunca integra el runtime Vue principal.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>Son comprobaciones dirigidas del host/SDK, no validación de cualquier paquete externo.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Existen rutas nativa, proceso, declarativa y <code>napi-vm</code> sobre QuickJS. WASM es una ranura opcional sin motor general activo en compilaciones normales. Las integraciones de ejemplo viven en <a href="https://github.com/nglmercer/plugins-example-tiktools" target="_blank" rel="noreferrer">plugins-example-tiktools</a>; aparecer en documentos antiguos no las convierte en funciones integradas.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si falla el descubrimiento, revisa compatibilidad, precedencia de raíces, destino y entrada. Si se deniega una intención, comprueba capacidades declaradas y concedidas sin eludir al host. Un inicio incierto exige reconciliación antes de sustituirlo. Los límites nativo/proceso mantienen confianza a nivel del sistema; el nombre del runtime no demuestra aislamiento.</p>`,14)])])}const g=a(t,[["render",o]]);export{h as __pageData,g as default};
